fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // If the remaining length of `main` from `start` is shorter than `sub`, no match is possible.
    if start + sub.len() > main.len() {
        return false;
    }
    // Compare element by element.
    for i in 0..sub.len() {
        if main[start + i] != sub[i] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // The empty `sub` always qualifies as a subarray.
    if sub.is_empty() {
        return true;
    }
    // If `sub` is longer than `main`, it cannot be a subarray.
    if sub.len() > main.len() {
        return false;
    }
    // Try every possible starting position.
    let max_start = main.len() - sub.len();
    for start in 0..=max_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}

